export interface ArticleReference {
  url: string;
  title_ar: string;
  source_type?: string;
}

export interface StaticArticle {
  id: string;
  title: string;
  title_ar: string;
  title_en?: string;
  slug: string;
  summary: string;
  summary_ar: string;
  summary_en?: string;
  content: string;
  content_ar: string;
  content_en?: string;
  author: string;
  featured_image_url: null;
  views: number;
  created_at: string;
  tags: string[];
  category_id?: string;
  metadata?: {
    references?: ArticleReference[];
    source_urls?: string[];
  };
}

type ArticleSeed = Omit<StaticArticle, "title" | "summary" | "content" | "content_ar" | "featured_image_url" | "views" | "created_at"> & {
  content_ar: string;
};

const reviewedAt = "2026-09-05T00:00:00.000Z";

function editorialArticle(seed: ArticleSeed): StaticArticle {
  return {
    ...seed,
    title: seed.title_ar,
    summary: seed.summary_ar,
    content: seed.content_ar,
    featured_image_url: null,
    views: 0,
    created_at: reviewedAt,
  };
}

